mapper.sql:
u.id,u.user_name,u.real_name,u.role_id,
case
    when u.id_card is null or u.id_card = '' then null
    else concat(left(u.id_card, 3), '***********', right(u.id_card, 4))
end as idCard,
u.organization,u.position,
case
    when u.phone is null or u.phone = '' then null
    else concat(left(u.phone, 3), '****', right(u.phone, 4))
end as phone,
u.avatar,u.create_time,u.status

mapper.update:
update t_user u
set u.grade_id = null
where u.id = #{userId}

mapper.select:
select
,r.role_name,g.grade_name,g.id as gradeId
from t_user u join t_role r on u.role_id = r.id left join t_grade g on u.grade_id = g.id where u.id = #{userId}
